'use strict';
const KEY='encore-v1', TM_KEY='encore-ticketmaster-consumer-key', BACKEND_KEY='encore-backend-url', CLOUD_KEY='encore-cloud-access-code';
function backendUrl(){const value=(window.ENCORE_PUBLIC_CONFIG?.backendUrl||localStorage.getItem(BACKEND_KEY)||'').trim().replace(/\/+$/,'');try{const u=new URL(value);return u.protocol==='https:'?u.origin:''}catch{return ''}}
function hasLookup(){return !!(backendUrl()||localStorage.getItem(TM_KEY))}
async function remoteApi(endpoint,params={},signal){const host=backendUrl();if(!host)throw Error('Connect your Vercel backend in Settings first.');const url=new URL(host+'/api/'+endpoint);for(const [key,val] of Object.entries(params))if(val!==undefined&&val!==null&&val!=='')url.searchParams.set(key,String(val));const jwt=await window.ENCORE_ACCOUNT?.getAccessToken?.();const response=await fetch(url,{signal,headers:{Accept:'application/json',...(jwt?{Authorization:'Bearer '+jwt}:{})}});let data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||`Connection failed (${response.status}).`);return data}

const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>Array.from(root.querySelectorAll(s));
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD'}).format(Number(n)||0);
const uid=()=>globalThis.crypto?.randomUUID?.()||`enc${Date.now()}${Math.floor(Math.random()*10000)}`;
const now=()=>new Date(), today=()=>localISO(now()), localISO=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
const dateOnly=s=>String(s||'').slice(0,10), parseDay=s=>{let a=dateOnly(s).split('-').map(Number);return a.length===3&&a.every(Number.isFinite)?new Date(a[0],a[1]-1,a[2]):new Date(NaN)};
const validDate=s=>/^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(parseDay(s))&&localISO(parseDay(s))===s;
const dateText=(s,opts={day:'numeric',month:'short',year:'numeric'})=>validDate(dateOnly(s))?parseDay(s).toLocaleDateString('en-AU',opts):'Date TBA';
const daysLeft=s=>Math.round((Date.UTC(parseDay(s).getFullYear(),parseDay(s).getMonth(),parseDay(s).getDate())-Date.UTC(now().getFullYear(),now().getMonth(),now().getDate()))/86400000);
const timeText=s=>{if(!s)return 'Time TBA';let [h,m]=s.split(':').map(Number);return Number.isFinite(h)?new Date(2000,0,1,h,m||0).toLocaleTimeString('en-AU',{hour:'numeric',minute:'2-digit'}):'Time TBA'};
const safeUrl=u=>{let v=String(u||'').trim();return /^(https:\/\/|data:image\/(jpeg|png|webp);base64,)/i.test(v)?v:''};
const getTime=c=>c.time!==undefined?c.time:(String(c.date||'').includes('T')?String(c.date).split('T')[1].slice(0,5):'');
const sum=(xs,k)=>Array.isArray(xs)?xs.reduce((a,b)=>a+(Number(b[k])||0),0):0;
const saved=c=>sum(c.deposits,'amount'), spent=c=>sum(c.expenses,'amount'), remaining=c=>Math.max(0,(Number(c.target)||0)-saved(c));
const statusText=s=>({scheduled:'Scheduled',rescheduled:'Rescheduled',postponed:'Postponed',cancelled:'Cancelled'})[s]||'Scheduled';
let lastRenderRoute=null;let db=loadDB(),route='home',selected=null,detailTab='overview',sheet=null,month=new Date(now().getFullYear(),now().getMonth(),1),draft=null,formStage='search',lookupResults=[],searchTimer=null,lookupAbort=null,lookupLoading=false,lookupError='',lookupQuery='',zoom=1,checking=false;
// A multi-user browser MUST NOT automatically read the old personal localStorage
// backup. Import it explicitly after signing into the correct account.
function loadDB(){return {concerts:[],settings:{}}}
function persist(){if(!window.ENCORE_ACCOUNT?.isReady())return;window.ENCORE_ACCOUNT.queueSave();syncNativeConcertWidget()}
window.ENCORE_READ_STATE=()=>({concerts:db.concerts,settings:db.settings||{}});
window.ENCORE_APPLY_STATE=(payload)=>{db={concerts:Array.isArray(payload?.concerts)?payload.concerts:[],settings:payload?.settings&&typeof payload.settings==='object'?payload.settings:{}};selected=null;route='home';render();syncNativeConcertWidget()};
window.ENCORE_REDRAW=()=>render();
window.ENCORE_ROUTE=()=>route;
window.ENCORE_TOAST=message=>toast(message);

// Only on future Capacitor builds: save a minimal snapshot into the iOS App Group.
// No Supabase token, expense records or personal cloud credentials leave this layer.
let lastNativeWidgetSignature='';
function syncNativeConcertWidget(){
 const plugin=window.Capacitor?.Plugins?.EncoreWidget;
 if(typeof plugin?.saveSnapshot!=='function')return;
 const next=upcoming().find(c=>!['cancelled','postponed'].includes(c.status));
 const payload=next ? {artist:String(next.artist||'').slice(0,120),date:dateOnly(next.date),venue:String(next.venue||'').slice(0,150),city:String(next.city||'').slice(0,100)} : {artist:'',date:'',venue:'',city:''};
 const signature=JSON.stringify(payload);
 if(signature===lastNativeWidgetSignature)return;
 Promise.resolve(plugin.saveSnapshot(payload)).then(()=>{lastNativeWidgetSignature=signature}).catch(()=>{});
}
function toast(message){let el=$('#toast');if(!el)return;el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3500)}
const all=()=>db.concerts, get=()=>all().find(c=>c.id===selected);
const upcoming=()=>all().filter(c=>!c.archived&&validDate(dateOnly(c.date))&&daysLeft(c.date)>=0).sort((a,b)=>daysLeft(a.date)-daysLeft(b.date));
const past=()=>all().filter(c=>c.archived||validDate(dateOnly(c.date))&&daysLeft(c.date)<0).sort((a,b)=>daysLeft(b.date)-daysLeft(a.date));
function icon(name,size=''){let paths={
 plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="m15 18-6-6 6-6"/>',chev:'<path d="m9 18 6-6-6-6"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',archive:'<rect x="3" y="4" width="18" height="4" rx="1"/><path d="M5 8v12h14V8m-10 5h6"/>',users:'<circle cx="9" cy="8" r="3"/><circle cx="17" cy="9" r="2"/><path d="M3 21v-2a6 6 0 0 1 12 0v2m0-6a5 5 0 0 1 6 5v1"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.8 1.8 0 0 0 .4 2l-2.1 2.1a1.8 1.8 0 0 0-2-.4l-.9.4v2.1h-3v-2.1l-1-.4a1.8 1.8 0 0 0-2 .4l-2.1-2.1a1.8 1.8 0 0 0 .4-2l-.4-1H4.6v-3h2.1l.4-1a1.8 1.8 0 0 0-.4-2l2.1-2.1a1.8 1.8 0 0 0 2 .4l1-.4V3.8h3v2.1l.9.4a1.8 1.8 0 0 0 2-.4l2.1 2.1a1.8 1.8 0 0 0-.4 2l.4 1h2.1v3h-2.1z"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 8-3 8-3 10h18c0-2-3-2-3-10m-8 13h4"/>',pin:'<path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',ticket:'<path d="M3 8V5h18v3a3 3 0 0 0 0 6v5H3v-5a3 3 0 0 0 0-6Z"/><path d="M13 5v14" stroke-dasharray="2 3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',wallet:'<rect x="2" y="5" width="20" height="15" rx="3"/><path d="M16 12h6M4 5V3h14"/>',music:'<path d="M9 18V5l12-2v12"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="15" r="3"/>',edit:'<path d="m4 20 4.2-.8L20 7.4 16.6 4 4.8 15.8 4 20Z"/>',check:'<path d="m4 12 5 5 11-11"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 20h16"/>',upload:'<path d="M12 18V5m-5 5 5-5 5 5M4 20h16"/>',trash:'<path d="M4 7h16M9 7V4h6v3m3 0-1 13H7L6 7m4 4v6m4-6v6"/>',external:'<path d="M13 4h7v7m0-7-9 9"/><path d="M19 14v6H4V5h6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',refresh:'<path d="M20 11a8 8 0 1 0-2 6m2 1v-5h-5"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="2"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',sparkle:'<path d="m12 2 2.3 6.7L21 11l-6.7 2.3L12 20l-2.3-6.7L3 11l6.7-2.3L12 2ZM19 19l1 3"/>',close:'<path d="M5 5 19 19M19 5 5 19"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M19 5l-1.5 1.5m-11 11L5 19"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h1M3 12h1M3 18h1"/>',save:'<path d="M4 4h14l2 2v14H4zM8 4v6h8V4M8 20v-7h8v7"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'};return `<svg class="icon ${size}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.info}</svg>`}
function art(c,cl='image-bg'){const url=safeUrl(c.posterUrl);return url?`<img class="${cl}" src="${e(url)}" alt="" loading="lazy">`:''}
function badge(c){let st=c.status||'scheduled',d=daysLeft(c.date);return st==='cancelled'?'<span class="pill danger">Cancelled</span>':st==='postponed'?'<span class="pill warning">Postponed</span>':st==='rescheduled'?'<span class="pill warning">Rescheduled</span>':d===0?'<span class="pill">Tonight!</span>':d>0?`<span class="pill">${d} days</span>`:'<span class="pill">Attended</span>'}
function card(c){return `<button class="event-card" data-open="${e(c.id)}" aria-label="Open ${e(c.artist)}"><div class="card-art">${art(c)}<strong>${e(c.artist)}</strong></div><div class="card-info"><div class="titleline"><strong>${e(c.artist)}</strong>${badge(c)}</div><p>${dateText(c.date,{day:'numeric',month:'short'})} · ${e(c.city||c.venue||'Location TBA')}</p></div></button>`}
function header(){return `<header class="topbar"><div class="wordmark">ENCORE<i>.</i></div><div class="top-actions"><button class="iconbtn" data-nav="settings" aria-label="Settings">${icon('settings')}</button></div></header>`}
function nav(){return `<nav class="bottom-nav" aria-label="Main navigation">${[['home','home','Home'],['calendar','calendar','Calendar'],['archive','archive','Archive'],['friends','users','Friends'],['settings','settings','Settings']].map(([id,ico,label])=>`<button class="navitem ${route===id?'active':''}" data-nav="${id}">${icon(ico)}<span>${label}</span></button>`).join('')}</nav>`}
function viewHome(){let u=upcoming(),next=u.find(c=>!['cancelled','postponed'].includes(c.status))||u[0];return `<div class="eyebrow">YOUR LIVE MUSIC ERA ✦</div><h1 style="margin-top:8px">Every show,<br><span style="background:var(--grad);color:transparent;background-clip:text">a story to tell.</span></h1><p class="title-sub">Count down the days. Plan the night. Keep the memories.</p>${next?`<button class="hero" data-open="${e(next.id)}" style="width:100%;text-align:left;color:inherit;padding:0"><div class="hero-glow"></div>${art(next)}<div class="hero-content"><div class="hero-top"><div class="overline">UP NEXT</div><div class="date-chip">${dateText(next.date,{day:'numeric',month:'short'}).toUpperCase()}</div></div><div><h2>${e(next.artist)}</h2><div class="hero-meta">${icon('pin','tiny')} ${e(next.venue||next.city||'Venue TBA')} ${next.city&&next.venue?'· '+e(next.city):''}</div><div class="hero-bottom" style="margin-top:24px"><span class="countdown-pill">${next.status==='cancelled'?'CANCELLED':next.status==='postponed'?'POSTPONED':daysLeft(next.date)===0?'IT’S SHOW DAY ✨':daysLeft(next.date)+' DAYS TO GO'}</span><span class="round-arrow">${icon('arrow')}</span></div></div></div></button>`:`<div class="empty" style="margin-top:22px"><div class="empty-art">✧ ♪ ✧</div><h3>Your next favourite memory starts here.</h3><p>Add the first show to start your countdown, plan your savings and keep everything together.</p><button class="btn" data-add>${icon('plus')} Add a concert</button></div>`}
<div class="insights"><div class="insight"><span class="insight-label">COMING UP</span><strong>${u.length}</strong></div><div class="insight"><span class="insight-label">TOTAL SPENT</span><strong>${money(all().reduce((s,c)=>s+spent(c),0))}</strong></div><div class="insight"><span class="insight-label">MEMORIES</span><strong>${past().length}</strong></div></div>
<div class="headline"><h2>On your calendar</h2><button class="linkbutton" data-nav="calendar">View all ${icon('arrow','tiny')}</button></div>${u.length?`<div class="stack-cards">${u.slice(0,6).map(card).join('')}</div>`:`<p style="margin-bottom:30px">When you've added a show, it'll appear here.</p>`}
${past().length?`<div class="headline"><h2>The afterglow</h2><button class="linkbutton" data-nav="archive">Archive ${icon('arrow','tiny')}</button></div><div class="stack-cards">${past().slice(0,2).map(card).join('')}</div>`:''}`}
function viewCalendar(){let y=month.getFullYear(),m=month.getMonth(),first=new Date(y,m,1).getDay(),n=new Date(y,m+1,0).getDate(),todayStr=today();let marks=new Map();for(let c of all()){if(!validDate(dateOnly(c.date)))continue;let d=parseDay(c.date);if(d.getFullYear()===y&&d.getMonth()===m){let k=d.getDate();marks.set(k,[...(marks.get(k)||[]),c])}}let days=['S','M','T','W','T','F','S'].map(d=>`<div class="cal-day header">${d}</div>`).join('');days+=Array.from({length:first},()=>'<div></div>').join('');for(let i=1;i<=n;i++){let d=localISO(new Date(y,m,i)),cs=marks.get(i)||[];days+=`<button class="cal-day ${cs.length?'has':''} ${d===todayStr?'today':''}" data-day="${e(d)}"><span class="num">${i}</span>${cs.length?'<div class="caldot"></div>':''}</button>`}return `<div class="eyebrow">YOUR PLANS</div><h1 style="margin-top:9px">The calendar</h1><p>Your countdowns, all in one place.</p><div class="panel"><div class="split"><button class="iconbtn" data-month="-1" aria-label="Previous month">${icon('back')}</button><h2>${month.toLocaleDateString('en-AU',{month:'long',year:'numeric'})}</h2><button class="iconbtn" data-month="1" aria-label="Next month">${icon('chev')}</button></div><div class="calendar-grid">${days}</div><p class="fine no-margin">Tap a highlighted date to see its shows.</p></div><div class="headline"><h2>Shows this month</h2><button class="linkbutton" data-add>${icon('plus','tiny')} Add</button></div><div class="cal-events">${[...marks.values()].flat().sort((a,b)=>dateOnly(a.date).localeCompare(dateOnly(b.date))).map(c=>`<button class="calendar-event" data-open="${e(c.id)}"><span class="datebox">${dateText(c.date,{month:'short'}).toUpperCase()}<strong>${parseDay(c.date).getDate()}</strong></span><span class="name">${e(c.artist)}<small>${e(c.venue||c.city||'Venue TBA')}</small></span>${icon('chev')}</button>`).join('')||'<div class="empty"><p>No shows this month yet.</p></div>'}</div>`}
function viewArchive(){let p=past();return `<div class="eyebrow">THE AFTERGLOW</div><h1 style="margin-top:9px">The archive</h1><p>Every concert, a little piece of your story.</p>${p.length?`<div class="stack-cards" style="margin-top:26px">${p.map(card).join('')}</div>`:`<div class="empty" style="margin-top:25px"><div class="empty-art">✦</div><h3>Your collection starts here</h3><p>Past concerts will show up automatically. You can add old shows any time.</p><button class="btn secondary" data-add>Add a past concert</button></div>`}`}
function viewSettings(){let backend=backendUrl(),legacy=localStorage.getItem(TM_KEY);return `<div class="eyebrow">MAKE IT YOURS</div><h1 style="margin-top:9px">Settings</h1><p>Personalise ENCORE and keep your concert memories safe.</p><div class="settings-group"><h2>Concert discovery</h2><div class="panel"><div class="split"><h3>ENCORE Vercel backend</h3><span class="pill">${backend?'Configured':'Not connected'}</span></div><p>Connect your Vercel address to search Ticketmaster and Ticketek, import Ticketek event links, and look up setlists. Your provider API keys stay on the server.</p><p class="fine">Managed ENCORE API: ${e(backend||'Not configured in account-config.js')}. Provider credentials stay in Vercel.</p></div></div><div class="settings-group"><h2>Your data</h2><div class="panel"><h3>Keep your memories safe</h3><p>Your concerts sync to your private account. Export a backup before major imports or changes.</p><div class="inline-actions"><button class="btn secondary" data-export>${icon('download')} Export backup</button><button class="btn ghost" data-import>${icon('upload')} Import backup</button><input type="file" id="backupInput" accept="application/json" hidden></div></div></div><div class="settings-group"><h2>Cloud & notifications</h2>
${window.ENCORE_ACCOUNT?.renderSettings?.()||'<div class="panel">Loading secure account…</div>'}
</div><div class="settings-group"><h2>Good to know</h2><div class="panel"><div class="listrow"><span>Saved reminder preferences<small>Available when cloud and iPhone push are enabled</small></span>${icon('bell')}</div><div class="listrow"><span>Event monitoring<small>Background checks run daily with cloud connected; in-app checks still work.</small></span>${icon('refresh')}</div><div class="listrow"><span>Install on iPhone<small>Safari → Share → Add to Home Screen</small></span>${icon('home')}</div></div></div><p class="fine">ENCORE v1.9 beta · Private accounts and ENCORE Together</p>`}
function contribution(c){let n=remaining(c),d=Math.max(1,daysLeft(c.date)),f=c.frequency||'daily',period=f==='daily'?1:f==='weekly'?7:14,periods=Math.max(1,Math.ceil(d/period));return {amount:Math.ceil(n/periods*100)/100,unit:f==='daily'?'day':f==='weekly'?'week':'fortnight'}}
function viewDetail(){let c=get();if(!c){route='home';return viewHome()}let d=daysLeft(c.date),st=c.status||'scheduled';return `<div class="detail-top"><button class="btn ghost small" data-back>${icon('back')} Back</button><div class="inline-actions" style="margin:0"><button class="btn secondary small" data-edit>${icon('edit')} Edit</button><button class="iconbtn" data-more aria-label="More concert options">${icon('more')}</button></div></div><div class="detail-hero">${art(c)}<div style="position:relative;z-index:1"><span class="eyebrow" style="color:#f1d6ff">${d<0?'THE MEMORY':st==='cancelled'?'EVENT CANCELLED':st==='postponed'?'DATE TO BE CONFIRMED':'LIVE IN '+e((c.city||'YOUR CITY').toUpperCase())}</span><h1>${e(c.artist)}</h1><p>${dateText(c.date)} · ${e(c.venue||'Venue TBA')}</p></div></div>
${c.pendingUpdate?`<div class="status-callout"><b>Heads up — event details changed</b><p style="color:inherit;margin:8px 0">${(c.pendingUpdate.changes||[]).map(e).join(' · ')}</p><div class="inline-actions"><button class="btn small" data-accept>Apply changes</button><button class="btn secondary small" data-dismiss>Dismiss</button></div></div>`:''}
${st!=='scheduled'?`<div class="status-callout ${st==='cancelled'?'danger':''}"><b>${statusText(st)}</b> — ${st==='cancelled'?'This concert was cancelled; savings and expenses are preserved.':st==='postponed'?'Waiting for a confirmed new date. The previous date is retained for reference.':'Check your updated ticket and travel arrangements.'}</div>`:''}
<div class="segmented">${[['overview','Overview'],['budget','Budget'],['info','Show info']].map(([id,t])=>`<button data-detail-tab="${id}" class="${detailTab===id?'active':''}">${t}</button>`).join('')}</div>
${detailTab==='overview'?detailOverview(c):detailTab==='budget'?detailBudget(c):detailInfo(c)}`}
function detailOverview(c){let d=daysLeft(c.date),st=c.status||'scheduled',co=contribution(c);return `<div class="info-grid"><div class="info-tile">${icon('clock')}<small>COUNTDOWN</small><strong>${st==='cancelled'?'Cancelled':st==='postponed'?'Postponed':d<0?'Show complete':d===0?'Today!':d+' days to go'}</strong></div><div class="info-tile">${icon('ticket')}<small>YOUR TICKET</small><strong>${c.ticketType==='seated'?'Reserved seat':c.ticketType==='ga'?'Standing / GA':'Not added'}</strong></div><div class="info-tile">${icon('calendar')}<small>DATE & TIME</small><strong>${dateText(c.date,{day:'numeric',month:'short'})}</strong><span class="subtext">${timeText(getTime(c))}</span></div><div class="info-tile">${icon('pin')}<small>VENUE</small><strong>${e(c.venue||'TBA')}</strong><span class="subtext">${e(c.city||'')}</span></div></div><div class="panel"><div class="panel-title"><h3>Your concert fund</h3><button class="linkbutton" data-detail-tab="budget">View budget ${icon('arrow','tiny')}</button></div>${c.target?`<div class="split"><span class="big-number">${money(saved(c))}</span><span class="muted" style="font-size:13px">of ${money(c.target)}</span></div><div class="progress"><i style="width:${Math.min(100,saved(c)/Number(c.target)*100)}%"></i></div><p style="margin:0">${remaining(c)>0&&d>=0?'Save '+money(co.amount)+' / '+co.unit+' to reach your target.':'You’re all caught up with this target.'}</p>`:`<p>Save up for merch, food and the little extras.</p><button class="btn secondary small" data-sheet="fund">${icon('plus')} Set a savings goal</button>`}</div><div class="panel"><div class="panel-title"><h3>Before the show</h3><button class="linkbutton" data-detail-tab="info">Show info ${icon('arrow','tiny')}</button></div><div class="listrow"><span>Doors open</span><strong>${timeText(c.doorsTime)}</strong></div><div class="listrow"><span>Headline act</span><strong>${timeText(c.headlineTime)}</strong></div><div class="listrow"><span>Event updates</span><span>${c.eventId?'Ticketmaster-linked':c.provider==='ticketek'?'Ticketek imported':c.provider==='qpac'?'QPAC/QTIX imported':c.provider==='official'?'Official link imported':'Manual concert'}</span></div></div>${c.notes?`<div class="panel"><h3>Notes to self</h3><p>${e(c.notes)}</p></div>`:''}<div class="inline-actions"><button class="btn secondary" data-ics>${icon('calendar')} Add to calendar</button>${safeUrl(c.link)?`<a class="btn ghost" target="_blank" rel="noopener noreferrer" href="${e(safeUrl(c.link))}">Official event ${icon('external','tiny')}</a>`:''}</div>`}
function detailBudget(c){let co=contribution(c),d=daysLeft(c.date),freq=c.frequency||'daily';return `<div class="panel"><div class="panel-title"><h3>Concert savings</h3><button class="linkbutton" data-sheet="fund">${icon('edit','tiny')} Edit plan</button></div>${c.target?`<div class="big-number">${money(saved(c))} <span class="muted" style="font-size:16px">/ ${money(c.target)}</span></div><div class="progress"><i style="width:${Math.min(100,saved(c)/Number(c.target)*100)}%"></i></div><div class="hint">${remaining(c)<=0?'🎉 You reached your target!':d<0?'The concert date has passed. You can still add or adjust your savings.':c.status==='postponed'||c.status==='cancelled'?'Your savings goal is on hold. Review your event status.':`Put aside <b>${money(co.amount)}</b> per ${co.unit} for the ${Math.max(1,d)} days remaining.`}</div><div class="inline-actions"><button class="btn" data-sheet="deposit">${icon('plus')} I saved money</button><button class="btn ghost" data-sheet="fund">Adjust goal</button></div>`:`<p>How much would you like to have available for this concert?</p><button class="btn" data-sheet="fund">${icon('plus')} Create savings plan</button>`}</div><div class="panel"><div class="panel-title"><h3>What you've spent</h3><button class="btn secondary small" data-sheet="expense">${icon('plus')} Add expense</button></div><div class="big-number">${money(spent(c))}</div><p>Keep track of tickets, transport, food, outfits and merch.</p>${(c.expenses||[]).length?c.expenses.slice().reverse().map(x=>`<div class="listrow"><span>${e(x.category||'Other')}<small>${e(x.note||dateText(x.date))}</small></span><strong>${money(x.amount)}</strong></div>`).join(''):'<p class="fine" style="margin:0">No expenses recorded yet.</p>'}</div>${(c.deposits||[]).length?`<div class="panel"><h3>Savings history</h3>${c.deposits.slice().reverse().map(x=>`<div class="listrow"><span>${dateText(x.date)}</span><strong style="color:#d9baff">+${money(x.amount)}</strong></div>`).join('')}</div>`:''}`}
function ticketType(c){return c.ticketType==='seated'?`Reserved seating ${[c.section?'Section '+c.section:'',c.row?'Row '+c.row:'',c.seat?'Seat '+c.seat:''].filter(Boolean).join(' · ')}`:c.ticketType==='ga'?'Standing / General Admission':'Not set yet'}
function detailInfo(c){let t=c.status||'scheduled',chart=safeUrl(c.seatmapUrl);return `<div class="panel"><div class="panel-title"><h3>Ticket & seating</h3><button class="linkbutton" data-edit>${icon('edit','tiny')} Edit</button></div><div class="info-tile"><small>YOUR TICKET TYPE</small><strong>${e(ticketType(c))}</strong></div>${chart?`<div class="split" style="margin-top:19px"><b>Venue seating chart</b><label class="fine">Zoom <input aria-label="Map zoom" class="map-zoom" id="mapZoom" type="range" min="1" max="3" step="0.25" value="${zoom}"></label></div><div class="map-scroll"><div class="map-content" id="mapContent" style="width:${zoom*100}%"><img src="${e(chart)}" alt="Event-specific seating chart (if provided by the event organiser)"><span class="map-pin" id="mapPin" style="display:${c.mapPin?'block':'none'};left:${c.mapPin?.x||50}%;top:${c.mapPin?.y||50}%"></span></div></div><p class="fine">Tap the chart to mark your approximate seat location. This is a manually placed marker, not an automatically verified exact seat.</p><button class="btn ghost small" data-clear-pin>Clear marker</button>`:`<p>Have a seat map? Add an image link or upload one through Edit concert to see it here.</p>`}</div><div class="panel"><div class="panel-title"><h3>Show times & setlist</h3><button class="btn secondary small" data-sheet="times">${icon('edit')} Update</button></div><div class="info-grid"><div class="info-tile"><small>DOORS OPEN</small><strong>${timeText(c.doorsTime)}</strong></div><div class="info-tile"><small>SUPPORT ACT</small><strong>${timeText(c.supportTime)}</strong></div><div class="info-tile"><small>HEADLINE ACT</small><strong>${timeText(c.headlineTime)}</strong></div><div class="info-tile"><small>START TIME</small><strong>${timeText(getTime(c))}</strong></div></div>${c.supportActs?`<p>Support acts: ${e(c.supportActs)}</p>`:''}${c.setlistNotes?`<p>${e(c.setlistNotes)}</p>`:''}<div class="inline-actions">${safeUrl(c.setlistUrl)?`<a class="btn ghost small" href="${e(safeUrl(c.setlistUrl))}" target="_blank" rel="noopener">Setlist link ${icon('external','tiny')}</a>`:''}<a class="btn ghost small" href="https://www.setlist.fm/search?query=${encodeURIComponent(c.artist)}" target="_blank" rel="noopener">Find setlists ${icon('external','tiny')}</a></div><p class="fine" style="margin-top:13px">Set times are still manually recorded. A setlist.fm lookup can show recent reported performances, but it does not confirm future show times.</p>${backendUrl()?`<button class="btn secondary small" data-setlists>${icon('music')} Browse recent setlists</button><div id="setlistResults" class="setlist-results"></div>`:''}</div><div class="panel"><div class="panel-title"><h3>Event watch</h3>${c.eventId?`<button class="btn secondary small" data-check>${icon('refresh')} Check now</button>`:''}</div>${c.eventId?`<p>Linked to Ticketmaster. ENCORE checks for changes to the date, time, venue or event status while the app is open.</p><p class="fine">Last checked: ${c.lastChecked?new Date(c.lastChecked).toLocaleString('en-AU'):'Not checked yet'}.</p>`:`<p>${c.provider==='ticketek'?'Imported from Ticketek. Automatic Ticketek status monitoring is not enabled yet; check the official event page for changes.':'This concert was added manually, so it is not linked to a live event listing. Edit the concert to update changes yourself.'}</p>`}${(c.changeHistory||[]).length?`<h4>Change history</h4>${c.changeHistory.slice().reverse().slice(0,8).map(x=>`<div class="listrow"><span>${e(x.summary)}<small>${new Date(x.at).toLocaleString('en-AU')}</small></span></div>`).join('')}`:''}<div class="notice">Checks work while the app is open; background push alerts aren't enabled yet. Official event pages remain the best source for urgent updates.</div></div><div class="panel"><div class="panel-title"><h3>Countdown reminders</h3><button class="linkbutton" data-sheet="reminders">${icon('edit','tiny')} Change</button></div><p>${c.reminderMode==='once'?'One reminder':c.reminderMode==='weekly'?'Weekly reminders':'Daily reminders'} starting ${Number(c.reminderDays)||14} days before, at ${e(c.reminderTime||'09:00')}.</p><div class="fine">Preferences are saved. Push notifications aren't active yet.</div></div>`}
function viewForm(){if(!draft)draft={artist:'',city:'',date:'',time:'',status:'scheduled',ticketType:'unknown'};return `<div class="page-head"><button class="iconbtn" data-back aria-label="Back">${icon('back')}</button><div><h1>${draft.id?'Edit concert':'Add a concert'}</h1><p>${draft.id?'Update the details that changed.':'First the show. Then everything else.'}</p></div></div><div class="flow-steps"><span class="active"></span><span class="${formStage==='details'?'active':''}"></span></div>${formStage==='search'&&!draft.id?searchStage():detailsStage()}`}
function searchStage(){let key=hasLookup();return `<div class="search-illustration"><div class="eyebrow">STEP 01 / FIND YOUR SHOW</div><h2 style="margin-top:8px">Who's taking the stage?</h2><p>Search upcoming shows or import an official event link.</p></div><label class="field" for="searchArtist">Artist or band</label><input class="input" id="searchArtist" placeholder="e.g. Harry Styles" autocomplete="off" value="${e(draft.artist||'')}"><label class="field" for="searchCity">City <small>(optional)</small></label><input class="input" id="searchCity" placeholder="e.g. Melbourne" autocomplete="off" value="${e(draft.city||'')}">${!key?`<div class="hint" style="margin-top:16px">${icon('sparkle','tiny')} To search official event sources, <button class="linkbutton" data-connect>connect your Vercel backend</button> in Settings. Manual entry still works.</div>`:`<div class="hint" style="margin-top:15px">Ticketmaster suggestions appear as you type. Melbourne searches also include nearby suburbs such as Docklands. The Search button adds Ticketek results (uses parser credits).</div>`}<div id="searchStatus" aria-live="polite" style="margin-top:13px"></div><div id="searchResults" class="search-results"></div>${key?`<div class="inline-actions"><button class="btn secondary full" data-search>${icon('search')} Search Ticketmaster + Ticketek</button></div>`:''}${backendUrl()?`<div class="official-import"><div class="divider-label">OR IMPORT FROM A LINK</div><label class="field" for="officialEventLink">Paste an official event page URL</label><input id="officialEventLink" class="input" type="url" autocapitalize="none" spellcheck="false" placeholder="Ticketmaster, Ticketek, QPAC, QTIX, Oztix…"><button class="btn secondary full" style="margin-top:10px" data-event-import>${icon('external')} Import official event link</button><div id="importStatus" aria-live="polite" class="fine" style="margin-top:9px">QPAC, QTIX and other sites are best-effort imports. You'll review the details before saving.</div></div>`:''}<div class="divider-label">OR</div><button class="btn ghost full" data-manual>${icon('plus')} Add concert manually ${icon('arrow','tiny')}</button><p class="fine" style="text-align:center;margin-top:12px">For past concerts or shows not available in a listing.</p>`}
function detailsStage(){let c=draft||{},date=dateOnly(c.date),time=getTime(c),poster=safeUrl(c.posterUrl),map=safeUrl(c.seatmapUrl);return `<div class="eyebrow">${c.id?'EDIT DETAILS':'STEP 02 / THE DETAILS'}</div><h2 style="margin:8px 0">Let's make it official.</h2><p>Only the artist and date are required. Everything else can be added later.</p>${c.importReview?`<div class="hint" style="margin:14px 0">${icon('info','tiny')} <strong>Imported from ${e(c.sourceHost||'official page')}.</strong> Please double-check the date, venue, time and ticket type. Some organisers block automatic reading; only confirmed fields were filled.</div>`:''}<form id="concertForm" novalidate><label class="field" for="artist">Artist / band *</label><input class="input" required id="artist" name="artist" placeholder="Artist name" value="${e(c.artist||'')}"><label class="field" for="title">Tour or concert name <small>(optional)</small></label><input class="input" id="title" name="title" placeholder="e.g. GUTS World Tour" value="${e(c.title||'')}"><div class="two"><div><label class="field" for="concertDate">Concert date *</label><input class="input" type="date" id="concertDate" name="date" required value="${e(date)}"></div><div><label class="field" for="concertTime">Time <small>(optional)</small></label><input class="input" type="time" id="concertTime" name="time" value="${e(time)}"></div></div><div class="two"><div><label class="field" for="venue">Venue</label><input class="input" id="venue" name="venue" placeholder="Venue TBA" value="${e(c.venue||'')}"></div><div><label class="field" for="city">City</label><input class="input" id="city" name="city" placeholder="Brisbane" value="${e(c.city||'')}"></div></div><div class="fine" style="margin-top:9px">${icon('info','tiny')} A venue may host both GA and seated shows. Check your actual ticket before selecting.</div><label class="field">What kind of ticket do you have?</label><input type="hidden" id="ticketType" name="ticketType" value="${e(c.ticketType||'unknown')}"><div class="choice-grid" id="ticketChoices"><button type="button" class="choice ${c.ticketType==='ga'?'selected':''}" data-ticket="ga">${icon('music')}<strong>Standing / GA</strong></button><button type="button" class="choice ${c.ticketType==='seated'?'selected':''}" data-ticket="seated">${icon('ticket')}<strong>Reserved seat</strong></button><button type="button" class="choice ${!c.ticketType||c.ticketType==='unknown'?'selected':''}" data-ticket="unknown">${icon('info')}<strong>Not sure yet</strong></button></div><div id="seatFields" style="display:${c.ticketType==='seated'?'block':'none'}"><div class="three"><div><label class="field">Section / block</label><input class="input" name="section" placeholder="S12" value="${e(c.section||'')}"></div><div><label class="field">Row</label><input class="input" name="row" placeholder="G" value="${e(c.row||'')}"></div><div><label class="field">Seat(s)</label><input class="input" name="seat" placeholder="14–15" value="${e(c.seat||'')}"></div></div></div><details class="expand"><summary>Artwork & venue map ${icon('image','tiny')}</summary><div class="expand-body"><p class="fine">Selected event artwork is added automatically where available. You can replace it with an image link or upload your own image.</p>${poster?`<img id="artPreview" src="${e(poster)}" alt="Concert artwork preview" style="width:100%;height:135px;object-fit:cover;border-radius:12px">`:'<div id="artPreview"></div>'}<label class="field">Poster image URL</label><input class="input" name="posterUrl" placeholder="https://..." value="${e(poster.startsWith('data:')?'':poster)}"><label class="field">Or upload poster (JPG, PNG, WebP)</label><input class="input" type="file" id="posterFile" accept="image/jpeg,image/png,image/webp"><label class="field">Venue map image URL</label><input class="input" name="seatmapUrl" placeholder="https://..." value="${e(map.startsWith('data:')?'':map)}"><label class="field">Or upload seating chart</label><input class="input" type="file" id="seatmapFile" accept="image/jpeg,image/png,image/webp"></div></details><details class="expand"><summary>More details ${icon('more','tiny')}</summary><div class="expand-body"><label class="field">Event status</label><select class="input" name="status"><option value="scheduled" ${!c.status||c.status==='scheduled'?'selected':''}>Scheduled</option><option value="rescheduled" ${c.status==='rescheduled'?'selected':''}>Rescheduled</option><option value="postponed" ${c.status==='postponed'?'selected':''}>Postponed</option><option value="cancelled" ${c.status==='cancelled'?'selected':''}>Cancelled</option></select><label class="field">Official event link</label><input class="input" name="link" type="url" placeholder="https://..." value="${e(c.link||'')}"><label class="field">Personal notes</label><textarea class="input" name="notes" placeholder="Outfit ideas, ticket notes, memories...">${e(c.notes||'')}</textarea></div></details><div id="saveError" role="alert" style="margin-top:12px"></div><div class="sticky-save"><button class="btn full" type="submit">${icon('check')} ${c.id?'Save changes':'Save concert'} ${icon('arrow','tiny')}</button></div></form>`}
function startAdd(){clearTimeout(searchTimer);selected=null;draft={artist:'',city:'',date:'',time:'',status:'scheduled',ticketType:'unknown'};lookupResults=[];lookupError='';lookupQuery='';formStage='search';route='form';render()}
function editConcert(){let c=get();if(!c)return;draft={...c,date:dateOnly(c.date),time:getTime(c)};formStage='details';route='form';render()}
function openConcert(id){if(!all().some(c=>c.id===id))return;selected=id;route='detail';detailTab='overview';zoom=1;render()}
function saveConcert(ev){ev.preventDefault();clearTimeout(searchTimer);let f=ev.target,x=Object.fromEntries(new FormData(f));x.artist=String(x.artist||'').trim();x.date=dateOnly(x.date);if(!x.artist){$('#saveError').innerHTML='<div class="hint error">Please enter an artist name.</div>';$('#artist')?.focus();return}if(!validDate(x.date)){$('#saveError').innerHTML='<div class="hint error">Choose a valid concert date. Time can be left blank.</div>';$('#concertDate')?.focus();return}let old=draft.id?all().find(c=>c.id===draft.id):null;if(!['ga','seated','unknown'].includes(x.ticketType))x.ticketType='unknown';if(x.ticketType!=='seated'){x.section='';x.row='';x.seat=''}let manualPoster=String(x.posterUrl||'').trim(),manualMap=String(x.seatmapUrl||'').trim();x.posterUrl=safeUrl(manualPoster)||(safeUrl(draft.posterUrl)||'');x.seatmapUrl=safeUrl(manualMap)||(safeUrl(draft.seatmapUrl)||'');x.link=safeUrl(x.link);if(old){let changes=[];for(let k of ['date','time','venue','city','status']){let before=k==='time'?getTime(old):k==='date'?dateOnly(old.date):old[k]||'';if(String(before)!==String(x[k]||''))changes.push(`${k}: ${before||'TBA'} → ${x[k]||'TBA'}`)}if(changes.length){old.changeHistory=old.changeHistory||[];old.changeHistory.push({at:new Date().toISOString(),summary:changes.join('; ')})}if(old.seatmapUrl!==x.seatmapUrl)old.mapPin=null;Object.assign(old,x)}else{let c={...x,id:uid(),archived:false,target:0,frequency:'daily',deposits:[],expenses:[],changeHistory:[],reminderMode:'daily',reminderDays:14,reminderTime:'09:00',eventId:draft.eventId||'',posterSource:draft.posterSource||'',eventNotices:draft.eventNotices||'',provider:draft.provider||'manual',doorsTime:draft.doorsTime||'',supportActs:draft.supportActs||'',sourceHost:draft.sourceHost||'',importReview:!!draft.importReview};db.concerts.push(c);selected=c.id}
try{persist()}catch(err){$('#saveError').innerHTML=`<div class="hint error">Could not save this concert. Device storage may be full (especially with large uploaded images). ${e(err.message)}</div>`;return}draft=null;route='detail';detailTab='overview';render();toast(old?'Concert updated ✨':'Concert saved! Let the countdown begin ✨')}
async function compressImage(file){if(!file)return null;if(!/^image\/(jpeg|png|webp)$/.test(file.type))throw Error('Please choose a JPG, PNG or WebP image.');if(file.size>10*1024*1024)throw Error('Please choose an image smaller than 10 MB.');const blob=URL.createObjectURL(file);try{let im=await new Promise((res,rej)=>{let i=new Image();i.onload=()=>res(i);i.onerror=()=>rej(Error('Could not read image'));i.src=blob});let w=Math.min(1050,im.naturalWidth),h=Math.max(1,Math.round(im.naturalHeight*w/im.naturalWidth));let cv=document.createElement('canvas');cv.width=w;cv.height=h;cv.getContext('2d').drawImage(im,0,0,w,h);return cv.toDataURL('image/jpeg',.75)}finally{URL.revokeObjectURL(blob)}}
function setTicketType(v){let x=$('#ticketType');if(!x)return;x.value=v;$$('[data-ticket]').forEach(b=>b.classList.toggle('selected',b.dataset.ticket===v));$('#seatFields').style.display=v==='seated'?'block':'none'}
function captureSearchDraft(){if(!draft||route!=='form'||formStage!=='search')return;draft.artist=$('#searchArtist')?.value.trim()||'';draft.city=$('#searchCity')?.value.trim()||''}
async function api(path,params={},signal){if(backendUrl()){const parts=/^events\/([^/]+)\.json$/.exec(path);return remoteApi('ticketmaster',parts?{eventId:decodeURIComponent(parts[1])}:{artist:params.keyword,city:params.city},signal)}let key=localStorage.getItem(TM_KEY);if(!key)throw Error('Add a Ticketmaster Consumer Key in Settings first.');let url=new URL(`https://app.ticketmaster.com/discovery/v2/${path}`);Object.entries({...params,apikey:key}).forEach(([k,v])=>{if(v!==undefined&&v!==null&&v!=='')url.searchParams.set(k,String(v))});let resp=await fetch(url,{signal});if(!resp.ok){if(resp.status===401||resp.status===403)throw Error('API key was rejected. Check the Consumer Key in Settings.');throw Error(`Event search unavailable (${resp.status}).`)}return resp.json()}
function eventFromTM(t){let venue=t._embedded?.venues?.[0]||{},image=(t.images||[]).slice().sort((a,b)=>(b.width||0)*(b.height||0)-(a.width||0)*(a.height||0)).find(x=>x.url)?.url||'',raw=t.dates?.start||{},state=String(t.dates?.status?.code||'').toLowerCase();return {artist:(t._embedded?.attractions||[]).find(x=>x.name)?.name||t.name||'',title:t.name||'',date:raw.localDate||'',time:raw.noSpecificTime?'':(raw.localTime||'').slice(0,5),venue:venue.name||'',city:venue.city?.name||'',status:state.includes('cancel')?'cancelled':state.includes('postpon')?'postponed':state.includes('resched')?'rescheduled':'scheduled',link:safeUrl(t.url),posterUrl:safeUrl(image),seatmapUrl:safeUrl(t.seatmap?.staticUrl),eventNotices:t.info||t.pleaseNote||'',eventId:t.id||'',posterSource:'Ticketmaster event image'}}
function resultsUI(){let box=$('#searchResults'),notice=$('#searchStatus');if(!box||!notice)return;notice.innerHTML=lookupLoading?'<div class="fine">Searching official event listings…</div>':lookupError?`<div class="hint error">${e(lookupError)}</div>`:lookupQuery&&lookupResults.length===0?'<div class="fine">No dated shows found. Try searching without a city, or paste the exact event link below.</div>':lookupResults.length?`<div class="fine">${lookupResults.length} listed event${lookupResults.length!==1?'s':''} found — tap the exact date you want.</div>`:'';box.innerHTML=lookupResults.map((x,i)=>`<button class="result" data-pick="${i}"><div class="thumb">${safeUrl(x.posterUrl)?`<img src="${e(x.posterUrl)}" alt="">`:'♪'}</div><span><strong>${e(x.title||x.artist)}</strong><small>${x.date?dateText(x.date):e(x.dateText||'Date TBA')} · ${e(x.venue||x.city||'Venue TBA')}</small><small>${e(x.provider==='ticketek'?'Ticketek':'Ticketmaster')}${x.city?' · '+e(x.city):''}</small></span>${icon('chev')}</button>`).join('')}
async function searchEvents(includeTicketek=false){captureSearchDraft();let artist=draft.artist,city=draft.city;if(!artist||artist.length<2){lookupError='Enter at least two characters of the artist name.';lookupResults=[];resultsUI();return}if(!hasLookup()){lookupError='Connect your Vercel backend in Settings to search for concerts.';lookupResults=[];resultsUI();return}if(lookupAbort)lookupAbort.abort();lookupAbort=new AbortController();let token=lookupAbort;lookupLoading=true;lookupError='';lookupQuery=`${artist} ${city}`;resultsUI();try{
 let matches=[],notes=[];
 if(backendUrl()){
  const calls=[api('events.json',{keyword:artist,city,size:20,sort:'date,asc'},token.signal)];if(includeTicketek)calls.push(remoteApi('ticketek',{mode:'search',query:[artist,city].filter(Boolean).join(' ')},token.signal));const outcomes=await Promise.allSettled(calls);
  if(token!==lookupAbort)return;
  if(outcomes[0].status==='fulfilled')matches.push(...(outcomes[0].value._embedded?.events||[]).map(eventFromTM).filter(x=>x.date).map(x=>({...x,provider:'ticketmaster'})));
  else notes.push('Ticketmaster: '+outcomes[0].reason.message);
  if(outcomes[1]?.status==='fulfilled'){
   const raw=outcomes[1].value.data?.data||outcomes[1].value.data||{};
   matches.push(...(raw.results||[]).filter(x=>x.event_url&&x.date_text&&!/waitlist|registration of interest/i.test(x.title||'')).map(x=>({artist:x.title||artist,title:x.title||artist,city:x.location||city,dateText:x.date_text||'',date:'',time:'',venue:x.location||'',link:x.event_url,posterUrl:safeUrl(x.image_url),provider:'ticketek',ticketekLink:x.event_url})));
  }else if(outcomes[1])notes.push('Ticketek: '+outcomes[1].reason.message);
 }else{
   const data=await api('events.json',{keyword:artist,city:city||undefined,size:20,sort:'date,asc'},token.signal);
   if(token!==lookupAbort)return;
   matches=(data._embedded?.events||[]).map(eventFromTM).filter(x=>x.date).map(x=>({...x,provider:'ticketmaster'}));
 }
 lookupResults=matches;lookupError=matches.length?'':notes.join(' · ');
 }catch(err){if(err.name==='AbortError')return;lookupError=err.message;lookupResults=[]}finally{if(token===lookupAbort){lookupLoading=false;resultsUI()}}}
function eventFromTicketek(payload,fallback=''){
 const d=payload?.data?.data||payload?.data||payload||{};
 return {artist:d.title||'',title:[d.title,d.subtitle].filter(Boolean).join(' — '),date:d.start_date||'',time:(d.start_time||'').slice(0,5),venue:d.venue||'',city:[d.suburb,d.state].filter(Boolean).join(', '),status:'scheduled',link:safeUrl(d.event_url||fallback),posterUrl:safeUrl(d.image_url),seatmapUrl:'',eventId:'',provider:'ticketek',posterSource:'Ticketek event image',eventNotices:d.description||''};
}
function eventLinkKind(raw){try{const u=new URL(raw),h=u.hostname.toLowerCase().replace(/^www\./,'');if(u.protocol!=='https:')return '';if(h==='ticketmaster.com.au'||h==='ticketmaster.com'||h.endsWith('.ticketmaster.com.au')||h.endsWith('.ticketmaster.com'))return 'ticketmaster';if(h==='premier.ticketek.com.au')return 'ticketek';if(['qpac.com.au','qtix.com.au','onthebanks.com.au','oztix.com.au','moshtix.com.au','eventbrite.com','eventbrite.com.au','frontiertouring.com','frontiertouring.com.au','livenation.com.au'].includes(h))return 'official';return ''}catch{return ''}}
function tmIdFromLink(raw){try{const u=new URL(raw),m=/\/event\/([A-Za-z0-9_-]{6,100})(?:\/|$)/.exec(u.pathname);return m?.[1]||u.searchParams.get('eventId')||''}catch{return ''}}
function importedDraft(x){const filled=Object.fromEntries(Object.entries(x).filter(([k,v])=>v!==undefined&&v!==null&&v!==''));draft={...draft,...filled,importReview:!!x.importReview};clearTimeout(searchTimer);if(lookupAbort)lookupAbort.abort();lookupAbort=null;formStage='details';render();window.scrollTo(0,0)}
async function importOfficialLink(){const raw=$('#officialEventLink')?.value.trim()||'';const kind=eventLinkKind(raw),status=$('#importStatus');if(!kind){if(status)status.innerHTML='<span class="hint error">Paste an HTTPS event link from a supported official provider.</span>';return}
 const button=$('[data-event-import]');if(button)button.disabled=true;
 if(status)status.textContent='Looking up this event…';
 try{
  let x;
  if(kind==='ticketmaster'){
   const id=tmIdFromLink(raw);if(!id)throw Error('This Ticketmaster link does not contain an event ID. Use the event page URL (…/event/ID).');
   const data=await remoteApi('ticketmaster',{eventId:id});x={...eventFromTM(data),provider:'ticketmaster',importReview:true};
  }else if(kind==='ticketek'){
   const result=await remoteApi('ticketek',{mode:'event',url:raw});x={...eventFromTicketek(result,raw),importReview:true};
  }else {
   const payload=await remoteApi('import-event',{url:raw});x={...payload.event,importReview:true};
  }
  if(!x.artist&&!x.title)throw Error('The page did not provide an artist or event title.');
  importedDraft(x);toast(x.date?'Concert details found — please review.':'Artist found. Please enter the concert date before saving.');
 }catch(err){
   if(status)status.innerHTML=`<div class="hint error">${e(err.message)} <button class="linkbutton" data-official-manual>Add this event manually instead</button></div>`;
 }finally{if(button)button.disabled=false}
}
function manualOfficialImport(){let url=$('#officialEventLink')?.value.trim()||'';if(!eventLinkKind(url))return toast('Use an official HTTPS event URL.');captureSearchDraft();draft={...draft,link:url,provider:eventLinkKind(url),importReview:true,sourceHost:new URL(url).hostname};formStage='details';render();toast('Please enter the missing details from the official page.')}
async function importTicketek(link){if(!backendUrl())return toast('Connect Vercel in Settings first.');if(!link)return toast('Paste a Ticketek event link.');try{toast('Getting Ticketek details…');const result=await remoteApi('ticketek',{mode:'event',url:link});const x=eventFromTicketek(result,link);if(!validDate(x.date))throw Error('Ticketek did not provide a usable date.');draft={...draft,...x,ticketType:'unknown'};clearTimeout(searchTimer);if(lookupAbort)lookupAbort.abort();formStage='details';render();toast('Ticketek event found — review and save.')}catch(err){toast('Ticketek import: '+err.message)}}
async function pickResult(i){let x=lookupResults[Number(i)];if(!x)return;if(x.provider==='ticketek')return importTicketek(x.ticketekLink||x.link);clearTimeout(searchTimer);draft={...draft,...x,ticketType:'unknown'};formStage='details';render();toast('Show found! Confirm the details and save.')}
function sheetHTML(){if(!sheet)return '';let c=get();if(!c)return '';const head=(title,subtitle='')=>`<div class="sheet-head"><h2>${title}</h2><button class="iconbtn" data-close aria-label="Close">${icon('close')}</button></div>${subtitle?`<p>${subtitle}</p>`:''}`;let body='';if(sheet==='fund'){body=head('Your savings plan','Set a goal for the extras you want to enjoy at this concert.')+`<form id="fundForm"><label class="field">How much do you want to save? (AUD)</label><input class="input" name="target" type="number" min="0" step="0.01" required value="${e(c.target||120)}"><label class="field">How often will you save?</label><select class="input" name="frequency"><option value="daily" ${!c.frequency||c.frequency==='daily'?'selected':''}>Every day</option><option value="weekly" ${c.frequency==='weekly'?'selected':''}>Every week</option><option value="fortnightly" ${c.frequency==='fortnightly'?'selected':''}>Every fortnight</option></select><p class="hint" style="margin-top:15px">We'll automatically recalculate your recommended contribution when you add savings, or when the concert gets closer.</p><button class="btn full" type="submit">Save savings plan</button></form>`}
else if(sheet==='deposit'){body=head('Money set aside ✨','A little goes a long way! Record what you put aside.')+`<form id="depositForm"><label class="field">Amount saved (AUD)</label><input class="input" type="number" name="amount" step="0.01" min="0.01" required placeholder="20.00"><label class="field">Date</label><input class="input" type="date" name="date" value="${today()}" required><button class="btn full">Add to concert fund</button></form>`}
else if(sheet==='expense'){body=head('Record an expense','Keep the entire night in perspective.')+`<form id="expenseForm"><label class="field">What was it?</label><select class="input" name="category">${['Tickets','Transport','Accommodation','Outfit','Merchandise','Food & drinks','Other'].map(x=>`<option>${x}</option>`).join('')}</select><label class="field">How much? (AUD)</label><input class="input" type="number" name="amount" min="0.01" step="0.01" required placeholder="35.00"><label class="field">Date</label><input class="input" type="date" name="date" value="${today()}" required><label class="field">Note <small>(optional)</small></label><input class="input" name="note" placeholder="e.g. Train tickets"><button class="btn full">Add expense</button></form>`}
else if(sheet==='times'){body=head('Setlist & show times','Use confirmed times from the organiser where possible.')+`<form id="timesForm"><div class="two"><div><label class="field">Doors open</label><input class="input" type="time" name="doorsTime" value="${e(c.doorsTime||'')}"></div><div><label class="field">Support act time</label><input class="input" type="time" name="supportTime" value="${e(c.supportTime||'')}"></div></div><label class="field">Headline act time</label><input class="input" type="time" name="headlineTime" value="${e(c.headlineTime||'')}"><label class="field">Support acts</label><input class="input" name="supportActs" value="${e(c.supportActs||'')}" placeholder="Opening artist names"><label class="field">Setlist notes</label><textarea class="input" name="setlistNotes" placeholder="Songs, sources, announcements">${e(c.setlistNotes||'')}</textarea><label class="field">Setlist source URL</label><input class="input" name="setlistUrl" value="${e(c.setlistUrl||'')}" placeholder="https://..."><button class="btn full">Save show information</button></form>`}
else if(sheet==='reminders'){body=head('Countdown reminders','Choose your countdown reminders. Cloud-connected devices can receive daily push batches.')+`<form id="remindersForm"><label class="field">Reminder frequency</label><select class="input" name="reminderMode"><option value="off" ${c.reminderMode==='off'?'selected':''}>No countdown reminders</option><option value="once" ${c.reminderMode==='once'?'selected':''}>Once before the concert</option><option value="daily" ${!c.reminderMode||c.reminderMode==='daily'?'selected':''}>Every day</option><option value="weekly" ${c.reminderMode==='weekly'?'selected':''}>Every week</option></select><label class="field">Start how many days before?</label><input class="input" type="number" min="1" max="365" name="reminderDays" value="${Number(c.reminderDays)||14}"><label class="field">Reminder time</label><input class="input" type="time" name="reminderTime" value="${e(c.reminderTime||'09:00')}"><div class="hint" style="margin-top:14px">Push requires cloud and notification permission in Settings. On the free Vercel plan, delivery happens in one daily batch at approximately 8–9 AM Brisbane, not your exact selected time.</div><label class="toggle-row"><input type="checkbox" name="eventAlerts" ${c.eventAlerts!==false?'checked':''}><span>Alert me to event changes (cancellations, times, venues)</span></label><label class="toggle-row"><input type="checkbox" name="savingsAlerts" ${c.savingsAlerts===true?'checked':''}><span>Remind me to add to my concert savings</span></label><button class="btn full">Save preferences</button></form>`}
else if(sheet==='more'){body=head('Concert options')+`<div style="display:grid;gap:10px"><button class="btn secondary full" data-archive>${icon('archive')} ${c.archived?'Unarchive concert':'Move to archive'}</button><button class="btn secondary full" data-ics>${icon('calendar')} Add to calendar</button><button class="btn danger full" data-delete>${icon('trash')} Delete concert</button></div>`}
return `<div class="overlay" id="overlay"><div class="sheet" role="dialog" aria-modal="true" aria-label="${e(sheet)}">${body}</div></div>`}
function showSheet(type){if(!get())return;sheet=type;renderSheet()}
function renderSheet(){let prev=$('#overlay');if(prev)prev.remove();if(!sheet)return;document.body.insertAdjacentHTML('beforeend',sheetHTML());$('#overlay')?.addEventListener('click',ev=>{if(ev.target.id==='overlay')closeSheet()});$('.sheet input')?.focus({preventScroll:true})}
function closeSheet(){sheet=null;$('#overlay')?.remove()}
function saveSheet(ev){ev.preventDefault();let c=get();if(!c)return;let x=Object.fromEntries(new FormData(ev.target)),type=ev.target.id;if(type==='fundForm'){let goal=Number(x.target);if(!Number.isFinite(goal)||goal<0)return toast('Enter a valid savings goal.');c.target=Math.round(goal*100)/100;c.frequency=x.frequency}
else if(type==='depositForm'||type==='expenseForm'){let amount=Number(x.amount);if(!(amount>0)||!validDate(x.date))return toast('Enter a valid amount and date.');let record={amount:Math.round(amount*100)/100,date:x.date};if(type==='depositForm'){c.deposits=c.deposits||[];c.deposits.push(record)}else{c.expenses=c.expenses||[];c.expenses.push({...record,category:x.category,note:x.note||''})}}
else if(type==='timesForm'){for(let k of ['doorsTime','supportTime','headlineTime','supportActs','setlistNotes'])c[k]=x[k]||'';c.setlistUrl=safeUrl(x.setlistUrl)}
else if(type==='remindersForm'){c.reminderMode=x.reminderMode;c.reminderDays=Math.max(1,Math.min(365,Number(x.reminderDays)||14));c.reminderTime=x.reminderTime||'09:00';c.eventAlerts=!!x.eventAlerts;c.savingsAlerts=!!x.savingsAlerts}
try{persist()}catch(err){return toast('Could not save: '+err.message)}closeSheet();render();toast('Saved successfully ✨')}
function exportBackup(){let b=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=`encore-backup-${today()}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('Backup downloaded')}
async function importBackup(file){if(!file)return;let j;try{j=JSON.parse(await file.text())}catch{return toast('This file is not valid JSON.')}if(!j||!Array.isArray(j.concerts))return toast('This is not an ENCORE backup.');if(!confirm(`Import ${j.concerts.length} concerts? This replaces this account’s concerts on the server. Export a backup first.`))return;if(!window.ENCORE_ACCOUNT?.isReady())return toast('Sign in before importing a backup.');
 if(j.concerts.length>150||file.size>1500000||j.concerts.some(c=>!c||typeof c!=='object'||typeof c.id!=='string'||typeof c.artist!=='string'))return toast('The backup is too large or contains invalid concerts.');
 let prev=db;db={concerts:j.concerts,settings:j.settings||{}};try{persist()}catch(err){db=prev;return toast('Import failed: '+err.message)}selected=null;route='home';render();toast('Backup imported. Wait for the cloud sync confirmation before closing ENCORE.')}
function downloadICS(c){if(!c||!validDate(dateOnly(c.date)))return toast('A valid concert date is required.');let d=dateOnly(c.date).replaceAll('-',''),start=d,end=localISO(new Date(parseDay(c.date).getTime()+86400000)).replaceAll('-','');let dt=getTime(c),dateFields='';if(dt&&/^\d{2}:\d{2}$/.test(dt)){let [hr,min]=dt.split(':').map(Number);let startDate=new Date(parseDay(c.date));startDate.setHours(hr,min,0,0);let endDate=new Date(startDate.getTime()+3*3600000);const stamp=v=>localISO(v).replaceAll('-','')+'T'+String(v.getHours()).padStart(2,'0')+String(v.getMinutes()).padStart(2,'0')+'00';dateFields=`DTSTART:${stamp(startDate)}\r\nDTEND:${stamp(endDate)}`}else{dateFields=`DTSTART;VALUE=DATE:${start}\r\nDTEND;VALUE=DATE:${end}`}let ices=s=>String(s||'').replaceAll('\\','\\\\').replace(/\r?\n/g,'\\n').replaceAll(',','\\,').replaceAll(';','\\;');let txt=`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//ENCORE//Concert Calendar//EN\r\nBEGIN:VEVENT\r\nUID:${c.id}@encore\r\nDTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+/,'')}\r\n${dateFields}\r\nSUMMARY:${ices(c.artist+(c.title&&c.title!==c.artist?' — '+c.title:''))}\r\nLOCATION:${ices([c.venue,c.city].filter(Boolean).join(', '))}\r\nDESCRIPTION:${ices(c.notes)}\r\nEND:VEVENT\r\nEND:VCALENDAR`;let file=new Blob([txt],{type:'text/calendar;charset=utf-8'}),url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=`encore-${c.artist.replace(/[^\w-]/g,'-').toLowerCase()}.ics`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('Calendar file downloaded')}
async function testBackend(){let box=$('#backendResult');if(!backendUrl()){toast('Save your Vercel URL first.');return}if(box)box.textContent='Checking connection…';try{let x=await remoteApi('health');if(box)box.textContent=`✓ Connected to ENCORE v${x.version}. Ticketmaster ${x.providers.ticketmaster?'ready':'needs key'} · Ticketek ${x.providers.ticketek?'ready':'needs key'} · setlist.fm ${x.providers.setlistfm?'ready':'needs key'} · Spotify ${x.providers.spotify?'ready':'optional'}.`;toast('Backend reachable!')}catch(err){if(box)box.textContent='Connection failed: '+err.message;toast('Connection test failed')}}
async function loadSetlists(){let c=get(),box=$('#setlistResults');if(!c||!box)return;box.innerHTML='<p class="fine">Looking up reported performances…</p>';try{let r=await remoteApi('setlists',{artist:c.artist});let list=(r.setlists||[]).filter(s=>s.songs?.length).slice(0,5);if(!list.length){box.innerHTML='<p class="fine">No reported song lists found for this artist. You can still add your own notes.</p>';return}box.innerHTML=`<div class="fine" style="margin:12px 0">Source: <a href="https://www.setlist.fm/" target="_blank" rel="noopener">setlist.fm</a> · Fan-reported historical performances, not confirmed predictions.</div>`+list.map(s=>`<details class="panel" style="margin-top:9px"><summary><b>${e(s.date)} · ${e(s.venue)}</b><span class="fine"> ${e(s.city)}</span></summary><ol style="padding-left:21px">${s.songs.map(song=>`<li style="margin:9px 0">${e(song.name)} ${song.cover?`<small class="fine">(cover: ${e(song.cover)})</small>`:''}<button class="linkbutton" data-spotify-track="${e(song.name)}" data-spotify-artist="${e(song.cover||s.artist)}">Open in Spotify ↗</button></li>`).join('')}</ol><a class="fine" href="${e(safeUrl(s.url))}" target="_blank" rel="noopener">See original setlist on setlist.fm ↗</a></details>`).join('');}catch(err){box.innerHTML=`<div class="hint error">${e(err.message)}</div>`}}
function openSpotifyTrack(song,artist){const query=[song,artist].filter(Boolean).join(' ');window.open('https://open.spotify.com/search/'+encodeURIComponent(query),'_blank','noopener,noreferrer')}
function differences(c,x){let diffs=[];for(let k of ['date','time','venue','city','status']){let old=k==='time'?getTime(c):k==='date'?dateOnly(c.date):c[k]||'';let newV=x[k]||'';if(k==='date'&&!newV)continue;if(String(old)!==String(newV))diffs.push(`${k==='time'?'Start time':k}: ${old||'TBA'} → ${newV||'TBA'}`)}if(x.seatmapUrl&&c.seatmapUrl&&x.seatmapUrl!==c.seatmapUrl)diffs.push('Seating chart changed');if(x.eventNotices&&c.eventNotices&&x.eventNotices!==c.eventNotices)diffs.push('Official event notes changed');return diffs}
async function checkLinked(c,loud=false){if(!c?.eventId){if(loud)toast('This concert is not linked to a live event.');return}if(!hasLookup()){if(loud)toast('Connect Vercel in Settings first.');return}if(checking){if(loud)toast('Already checking an event.');return}if(!navigator.onLine){if(loud)toast('Go online to check event changes.');return}checking=true;try{let data=await api('events/'+encodeURIComponent(c.eventId)+'.json'),x=eventFromTM(data),old=all().find(z=>z.id===c.id);if(!old)return;old.lastChecked=new Date().toISOString();let diffs=differences(old,x);if(diffs.length&&old.ignoredFingerprint!==JSON.stringify(x)){old.pendingUpdate={latest:x,changes:diffs,at:old.lastChecked,link:x.link};if(loud)toast('Event changes found — please review.')}else if(loud)toast(diffs.length?'Previously dismissed changes.':'No changes reported by Ticketmaster.');persist();if(route==='detail'&&selected===c.id)render()}catch(err){if(loud)toast('Could not check event: '+err.message)}finally{checking=false}}
function applyPending(){let c=get();if(!c?.pendingUpdate)return;let x=c.pendingUpdate.latest;for(let k of ['date','time','venue','city','status']){if(x[k]!==undefined&&(k!=='date'||validDate(x[k])))c[k]=x[k]}if(x.link)c.link=x.link;if(x.eventNotices!==undefined)c.eventNotices=x.eventNotices;if(x.seatmapUrl&&x.seatmapUrl!==c.seatmapUrl){c.seatmapUrl=x.seatmapUrl;c.mapPin=null}c.changeHistory=c.changeHistory||[];c.changeHistory.push({at:new Date().toISOString(),summary:'Provider update: '+c.pendingUpdate.changes.join('; ')});delete c.pendingUpdate;c.ignoredFingerprint='';persist();render();toast('Event details updated')}
async function checkDue(){if(!window.ENCORE_ACCOUNT?.isReady()||!hasLookup()||!navigator.onLine)return;for(let c of all()){if(!c.eventId||c.archived||daysLeft(c.date)<-3||daysLeft(c.date)>370)continue;if(c.lastChecked&&Date.now()-new Date(c.lastChecked).getTime()<12*3600*1000)continue;await checkLinked(c,false)}}
function onClick(ev){let b=ev.target.closest('button,[data-open]');if(!b||(!b.closest('#app')&&!b.closest('#overlay')))return;let d=b.dataset;
if('nav'in d){closeSheet();route=d.nav;selected=null;render();window.scrollTo(0,0)}
else if('add'in d)startAdd();
else if('open'in d)openConcert(d.open);
else if('back'in d){if(route==='form'&&formStage==='details'&&!draft.id){let f=$('#concertForm');if(f){Object.assign(draft,Object.fromEntries(new FormData(f)));draft.posterUrl=safeUrl(draft.posterUrl)||draft.posterUrl;draft.seatmapUrl=safeUrl(draft.seatmapUrl)||draft.seatmapUrl}formStage='search';render();window.scrollTo(0,0)}else if(route==='form'&&draft?.id){selected=draft.id;route='detail';render()}else{route='home';selected=null;render()}}
else if('month'in d){month=new Date(month.getFullYear(),month.getMonth()+Number(d.month),1);render()}
else if('day'in d){let cs=all().filter(c=>dateOnly(c.date)===d.day);if(cs.length===1)openConcert(cs[0].id);else if(cs.length)toast(`${cs.length} shows on this date — see the list below.`);else toast('No shows on this date yet.')}
else if('detailTab'in d){detailTab=d.detailTab;render();$('.segmented')?.scrollIntoView({block:'start',behavior:'instant'})}
else if('manual'in d){clearTimeout(searchTimer);captureSearchDraft();formStage='details';render();window.scrollTo(0,0)}
else if('search'in d)searchEvents(true);
else if('ticketekImport'in d)importTicketek($('#ticketekLink')?.value.trim());
else if('eventImport'in d)importOfficialLink();
else if('officialManual'in d)manualOfficialImport();
else if('setlists'in d)loadSetlists();
else if('spotifyTrack'in d)openSpotifyTrack(d.spotifyTrack,d.spotifyArtist);
else if('pick'in d)pickResult(d.pick);
else if('ticket'in d)setTicketType(d.ticket);
else if('edit'in d)editConcert();
else if('sheet'in d)showSheet(d.sheet);
else if('more'in d)showSheet('more');
else if('close'in d)closeSheet();
else if('export'in d)exportBackup();
else if('import'in d)$('#backupInput')?.click();
else if('backendSave'in d){let raw=$('#backendInput')?.value.trim().replace(/\/+$/,'')||'';let host='';try{const u=new URL(raw);if(u.protocol==='https:')host=u.origin}catch{}if(!host)return toast('Enter your HTTPS Vercel address.');localStorage.setItem(BACKEND_KEY,host);render();toast('Vercel backend URL saved. Test your connection next.')}
else if('backendClear'in d){localStorage.removeItem(BACKEND_KEY);render();toast('Vercel backend disconnected.')}
else if('backendTest'in d)testBackend();
else if('connect'in d){route='settings';render();window.scrollTo(0,0)}
else if('check'in d)checkLinked(get(),true);
else if('accept'in d){let c=get();if(c?.pendingUpdate?._fingerprint)ackAlert(c.id,c.pendingUpdate._fingerprint);applyPending();}
else if('dismiss'in d){let c=get();if(!c?.pendingUpdate)return;c.ignoredFingerprint=JSON.stringify(c.pendingUpdate.latest);delete c.pendingUpdate;persist();render();toast('Update dismissed.')}
else if('archive'in d){let c=get();c.archived=!c.archived;persist();closeSheet();route=c.archived?'archive':'detail';render();toast(c.archived?'Moved to archive':'Restored to upcoming concerts')}
else if('delete'in d){let c=get();if(!confirm(`Permanently delete ${c.artist}? This also deletes its local budget, expenses, seats and notes.`))return;db.concerts=db.concerts.filter(x=>x.id!==c.id);persist();closeSheet();selected=null;route='home';render();toast('Concert deleted')}
else if('ics'in d)downloadICS(get());
else if('clearPin'in d){get().mapPin=null;persist();render();toast('Map marker removed')}
}
function onInput(ev){if(ev.target.id==='searchArtist'||ev.target.id==='searchCity'){captureSearchDraft();clearTimeout(searchTimer);if(hasLookup()&&draft.artist.length>=3){searchTimer=setTimeout(searchEvents,800)}else{lookupResults=[];lookupError='';lookupQuery='';resultsUI()}}
else if(ev.target.id==='mapZoom'){zoom=Number(ev.target.value);let content=$('#mapContent');if(content)content.style.width=zoom*100+'%'}
else if(ev.target.name==='posterUrl'){draft.posterUrl=safeUrl(ev.target.value)}
else if(ev.target.name==='seatmapUrl'){draft.seatmapUrl=safeUrl(ev.target.value)}
}
async function onChange(ev){if(ev.target.id==='backupInput'){importBackup(ev.target.files[0]);return}if(['posterFile','seatmapFile'].includes(ev.target.id)){let file=ev.target.files?.[0];if(!file)return;try{let data=await compressImage(file);let key=ev.target.id==='posterFile'?'posterUrl':'seatmapUrl';draft[key]=data;let input=$(`[name=${key}]`);if(input)input.value='';if(key==='posterUrl'){let box=$('#artPreview');if(box)box.outerHTML=`<img id="artPreview" src="${data}" alt="Uploaded poster preview" style="width:100%;height:135px;object-fit:cover;border-radius:12px">`}toast('Image added. Save concert to keep it.')}catch(err){toast(err.message)}}}
function onSubmit(ev){if(ev.target.id==='concertForm')saveConcert(ev);else if(['fundForm','depositForm','expenseForm','timesForm','remindersForm'].includes(ev.target.id))saveSheet(ev)}
function render(){let app=$('#app');if(!app)return;let routeChanged=lastRenderRoute!==route;lastRenderRoute=route;let main=route==='home'?viewHome():route==='calendar'?viewCalendar():route==='archive'?viewArchive():route==='friends'?(window.ENCORE_ACCOUNT?.renderFriends?.()||'<p>Loading friends…</p>'):route==='settings'?viewSettings():route==='detail'?viewDetail():viewForm();let showNav=!['form'].includes(route);app.innerHTML=`<div class="app-shell">${route==='form'||route==='detail'?'':header()}<main>${main}</main></div>${showNav?nav():''}${['home','calendar','archive'].includes(route)?`<button class="fab" aria-label="Add concert" data-add>${icon('plus')}</button>`:''}`;renderSheet();if(routeChanged)window.scrollTo(0,0);window.ENCORE_ACCOUNT?.onRender?.();if(route==='friends'&&routeChanged)window.ENCORE_ACCOUNT?.loadFriends?.()}

